INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 49, 'theory', 'Quiz: rooms and messages API');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 49, 0, 'Which method suits an idempotent "join the room"?', '["POST", "PUT on /rooms/{id}/members/me — a repeat does not change the result", "GET", "PATCH with no body"]', 1, 'PUT sets the state "I am a member": calling it again gives the same result.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 49, 1, 'How should the length of a message text be counted?', '["In bytes", "In characters (chars)", "In words", "No limit"]', 1, 'Cyrillic in UTF-8 takes two bytes per letter; a limit in bytes is unfair to non-Latin text.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 49, 2, 'Why is an idempotency key needed when sending a message?', '["To encrypt the text", "So that repeating the same send does not create a duplicate", "To speed up the insert", "To order the messages"]', 1, 'If the response is lost, the client repeats the request; a unique key turns the repeat into a harmless operation.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 49, 3, 'Why is cursor pagination (before id N) better than a page number?', '["It is easier to read", "It does not slow down on deep pages and does not \"shift\" when new messages arrive", "It forbids new messages", "There is no difference"]', 1, 'A cursor uses the index; new messages at the top do not move what has already been read.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 49, 4, 'What should the server answer a non-member who requests a private room?', '["403 Forbidden", "The same as for a nonexistent room: 404", "200 with an empty list", "500"]', 1, 'Otherwise the difference between responses would reveal which private rooms exist.');
